        assert.deepEqual(calls, [
            { workspace: 'my-owner', repository: 'my-repo', pullRequestId: '5', event: 'APPROVE', body: '' },

        { workspace: 'my-owner', repository: 'my-repo', pullRequestId: '5', event: 'APPROVE', body: '' },
        { workspace: 'my-owner', repository: 'my-repo', pullRequestId: '5', event: 'COMMENT', body: 'note' }
